# -*- coding: utf-8 -*-
"""Phan mo rong ESD (Tooley Ch.12, tr.197-206) gan vao ghi chu cua Module 09. Khong co slide cua giang vien cho phan nay. Bang 12.1, 12.2 doc tren anh trang tr.200, 201."""
from hx import *

def esd(lang):
    vi = lang == 'vi'
    t121 = [('đi trên thảm len/nylon', 'walking over a wool/nylon carpet', '35 kV', '1,5 kV', '1.5 kV'), ('trượt hộp nhựa trên thảm', 'sliding a plastic box across a carpet', '18 kV', '1,2 kV', '1.2 kV'), ('lấy linh kiện khỏi túi polystyrene', 'removing parts from a polystyrene bag', '15 kV', '1 kV', '1 kV'),
            ('đi trên sàn vinyl', 'walking over vinyl flooring', '11 kV', '350 V', '350 V'), ('bóc màng co', 'removing shrink-wrap packaging', '10 kV', '250 V', '250 V'), ('làm việc ở bàn, mặc áo yếm', 'working at a bench wearing overalls', '8 kV', '150 V', '150 V')]
    t122 = [('logic CMOS', 'CMOS logic', '250 V đến 1 kV', '250 V to 1 kV'), ('logic TTL', 'TTL logic', '550 V đến 2,5 kV', '550 V to 2.5 kV'), ('transistor lưỡng cực', 'bipolar junction transistors', '150 V đến 5 kV', '150 V to 5 kV'), ('bộ nhớ động', 'dynamic memories', '20 V đến 100 V', '20 V to 100 V'),
            ('vi xử lý VLSI', 'VLSI microprocessors', '20 V đến 100 V', '20 V to 100 V'), ('MOSFET', 'MOSFETs', '50 V đến 350 V', '50 V to 350 V'), ('điện trở màng mỏng', 'thin-film resistors', '300 V đến 3 kV', '300 V to 3 kV'), ('chỉnh lưu có điều khiển (SCR)', 'silicon-controlled rectifiers', '4 kV đến 15 kV', '4 kV to 15 kV')]
    if vi:
        h = '<h3 id="esd">Phần mở rộng: phóng tĩnh điện (ESD), Tooley Chương 12</h3><p class="srcnote">Phần này không có slide của giảng viên; dựng từ Tooley 12.1 đến 12.4 (tr.197 đến 206). 8 câu gốc (khoá A.12) và 17 câu bổ sung cùng 2 bài tự luận nằm trong ngân hàng của Module 09, chủ đề "Phóng tĩnh điện (ESD)".</p>'
        h += '<p>Linh kiện nhạy tĩnh điện (ESD) có thể hỏng hoàn toàn mà không có dấu hiệu hư hại nhìn thấy, nhất là LSI, VLSI, transistor MOS, diode vi sóng và màn hình. Điện tích sinh ra khi hai vật không dẫn điện khác loại cọ xát; <b>thang tĩnh điện ma sát (triboelectric)</b> xếp vật liệu từ dương (da thuộc, thuỷ tinh, len, lụa, nhôm, giấy) qua trung tính (bông, thép) đến âm (gỗ, cao su cứng, polyester, polystyrene, PVC, Teflon âm nhất). Điện tích lớn nhất khi hai vật ở hai đầu mút của thang (PVC cọ thuỷ tinh, polyester cọ da khô). Không khí khô làm điện tích tích tụ nhiều hơn rất nhiều:</p>'
        h += table(['Tình huống', 'Độ ẩm 20 %', 'Độ ẩm 80 %'], [[a, b, c] for a, _, b, c, _ in t121]) + '<p>Linh kiện hiệu ứng trường nhạy hơn linh kiện lưỡng cực; linh kiện lắp trên mạch in ít nguy cơ hơn linh kiện rời vì các đường dẫn xả điện tích:</p>' + table(['Loại linh kiện', 'Ngưỡng nhạy điển hình'], [[a, c] for a, _, c, _ in t122])
        h += '<p><b>Xử lý và vận chuyển:</b> vòng cổ tay nối đất qua dây có điện trở 1 MΩ (hạn chế dòng qua người nếu chạm vật mang điện), dây đeo gót, thảm sàn và bàn tiêu tán tĩnh điện, tránh nơi quá khô, ổ nối đất, thiết bị thử nối đất, mỏ hàn điện áp thấp nối đất, dụng cụ cắm và rút IC chống tĩnh điện, tránh nguồn cao áp (đèn huỳnh quang), và để linh kiện trong bao bì chống tĩnh điện cho tới khi dùng. Ba loại vật liệu bảo vệ: <b>dẫn điện</b> (lá kim loại, vật liệu tẩm cacbon; bảo vệ nhiều nhất), <b>tiêu tán tĩnh điện</b> (rẻ hơn) và <b>chống tĩnh điện</b> (trung tính trên thang ma sát như bìa, bông, gỗ; bảo vệ ít nhất). Nhãn cảnh báo thường chữ đen trên nền vàng.</p>'
        h += '<p>Ví dụ số (kiểm bằng chương trình): đi trên thảm len/nylon cho 35 kV ở độ ẩm 20 % so với 1,5 kV ở 80 %, gấp 23,3 lần; vi xử lý VLSI chỉ chịu 20 V đến 100 V nên 1,5 kV vẫn gấp 15 lần ngưỡng cao nhất. Dòng giới hạn của dây đeo tay 1 MΩ khi chạm vật 230 V (minh hoạ của site, bỏ qua điện trở cơ thể) là 0,23 mA.</p>'
    else:
        h = '<h3 id="esd">Extension: electrostatic discharge (ESD), Tooley Chapter 12</h3><p class="srcnote">There are no lecturer slides for this part; it is built from Tooley 12.1 to 12.4 (pp.197 to 206). 8 original questions (key A.12) and 17 added questions plus 2 worked problems are in the Module 09 bank under the topic "Electrostatic discharge (ESD)".</p>'
        h += '<p>Electrostatic-sensitive devices (ESDs) can fail totally without any visible damage, especially LSI, VLSI, MOS transistors, microwave diodes and displays. Charge is made when two dissimilar non-conductors are rubbed together; the <b>triboelectric series</b> ranks materials from positive (leather, glass, wool, silk, aluminium, paper) through neutral (cotton, steel) to negative (wood, hard rubber, polyester, polystyrene, PVC, Teflon the most negative). The largest charge comes from materials at the extreme ends of the scale (PVC on glass, polyester on dry skin). Dry air lets far more charge build up:</p>'
        h += table(['Situation', '20 % humidity', '80 % humidity'], [[b, c, d] for _, b, _, _, d in [(x[0], x[1], x[2], x[3], x[4]) for x in t121] for c in [x for x in t121 if x[1] == b][0][2:3] for d in [[x for x in t121 if x[1] == b][0][4]]]) + '<p>Field-effect devices are more sensitive than bipolar ones; components mounted on a printed circuit are at less risk than loose ones because the conductive tracks dissipate charge:</p>' + table(['Type of device', 'Typical static susceptibility'], [[b, d] for _, b, _, d in t122])
        h += '<p><b>Handling and transport:</b> a grounded wrist strap whose lead has a 1 MΩ resistor (limiting the current through the wearer on contact with a live conductor), heel straps, static-dissipative floor and bench mats, avoiding very dry places, ground jacks, grounded test equipment, low-voltage grounded soldering irons, anti-static IC insertion and removal tools, avoiding high-voltage sources (fluorescent lights), and keeping parts in anti-static packaging until needed. Three classes of protective material: <b>conductive</b> (metal foils, carbon-impregnated plastics; the most protection), <b>static dissipative</b> (cheaper) and <b>anti-static</b> (neutral on the triboelectric scale, such as cardboard, cotton and wood; the least protection). Warning labels are usually black text on yellow.</p>'
        h += '<p>Numeric examples (checked by program): walking over a wool/nylon carpet gives 35 kV at 20 % humidity against 1.5 kV at 80 %, 23.3 times more; a VLSI microprocessor withstands only 20 V to 100 V so 1.5 kV is still 15 times its upper threshold. The current limited by a 1 MΩ wrist strap touching a 230 V conductor (the site\'s illustration, ignoring body resistance) is 0.23 mA.</p>'
    return h
